// Each registered explorer keeps an independent save in this browser.
let registeredExplorer=null;try{registeredExplorer=JSON.parse(localStorage.getItem('magnolia-explorer-v1'))}catch{}
const explorerId=registeredExplorer?.id||'';
const gameStorage={getItem:k=>localStorage.getItem(explorerId?'magnolia-save:'+explorerId+':'+k:k),setItem:(k,v)=>localStorage.setItem(explorerId?'magnolia-save:'+explorerId+':'+k:k,v),removeItem:k=>localStorage.removeItem(explorerId?'magnolia-save:'+explorerId+':'+k:k)};

// On-demand decoding keeps unused costumes out of the initial page payload.
function magnoliaInlineAsset(url){
  return fetch(url).then(response=>{
    if(!response.ok)throw new Error('이미지 로딩 실패: '+response.status+' '+url);
    return response.blob();
  }).then(blob=>new Promise((resolve,reject)=>{
    const reader=new FileReader();reader.onload=()=>resolve(reader.result);
    reader.onerror=()=>reject(reader.error||new Error('이미지 변환 실패'));
    reader.readAsDataURL(blob);
  }));
}

function htmlSafe(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

