let magnoliaLastDraw=0;
function magnoliaFrame(now){
  requestAnimationFrame(magnoliaFrame);
  if(document.hidden){last=now;magnoliaLastDraw=now;return;}
  const overlayOpen=!document.getElementById('modal').classList.contains('hidden');
  const interval=1000/(overlayOpen?15:30);
  if(magnoliaLastDraw&&now-magnoliaLastDraw<interval-1)return;
  magnoliaLastDraw=now;
  render(now);
}
