function fusionLab(){fusionPick=[];drawLab()}
function selectFusion(i){if(fusionPick.includes(i))fusionPick=fusionPick.filter(n=>n!==i);else if(fusionPick.length<2)fusionPick.push(i);else toast('먼저 선택한 친구를 눌러 해제해 줘.');drawLab()}
function drawLab(){let pair=[...fusionPick].sort((a,b)=>a-b),exists=fusions.some(f=>f[0]===pair[0]&&f[1]===pair[1]);modal(`<button class="close" onclick="closeModal()">×</button><span class="tag">FRIENDSHIP FUSION LAB</span><h2>별빛 합성 연구소</h2><p>수집한 서로 다른 친구 2마리의 힘을 모아 새 친구를 만들어요.<br><b>원래 친구는 사라지지 않아요.</b> 조합마다 새로운 색과 이름이 생겨요.</p>${caught.size<2?'<p class="notice">먼저 숲에서 친구를 2마리 이상 모아 주세요!</p>':''}<div class="fusion-slots">${[0,1].map(n=>`<div>${fusionPick[n]===undefined?'<span>＋</span>':svg(fusionPick[n])}</div>`).join('<b>+</b>')}</div><div class="grid">${[...caught].sort((a,b)=>a-b).map(i=>`<button class="dexitem ${fusionPick.includes(i)?'chosen':''}" onclick="selectFusion(${i})">${svg(i)}<b>${creatures[i][0]}</b></button>`).join('')}</div><p><button class="primary" ${pair.length!==2||exists?'disabled':''} onclick="doFusion()">${exists?'이미 발견한 조합이에요':'두 친구의 힘 합치기 ✦'}</button></p><h3>합성 친구 도감 · ${fusions.length} / 45</h3><div class="grid">${fusions.map(([a,b])=>`<div class="dexitem">${fusionSvg(a,b)}<b>${creatures[a][0].slice(0,2)}${creatures[b][0].slice(0,2)}링</b><p style="font-size:10px">${creatures[a][1]} + ${creatures[b][1]}</p></div>`).join('')}</div>`)}
function doFusion(){if(fusionPick.length!==2)return;let [a,b]=[...fusionPick].sort((a,b)=>a-b);if(a===b||!caught.has(a)||!caught.has(b)||fusions.some(f=>f[0]===a&&f[1]===b))return;fusions.push([a,b]);gameStorage.setItem('sparkwood-fusions',JSON.stringify(fusions));modal(`<div class="intro"><span class="tag">A NEW FRIEND IS BORN</span><div class="fusion-born">${fusionSvg(a,b)}</div><h2>${creatures[a][0].slice(0,2)}${creatures[b][0].slice(0,2)}링 탄생!</h2><p>${creatures[a][0]}의 ${creatures[a][1]} 능력과<br>${creatures[b][0]}의 ${creatures[b][1]} 능력이 만났어!<br><small>친구 합성은 게임 속 상상 설정이에요.</small></p><button class="primary" onclick="fusionLab()">합성 도감 보기</button> <button class="secondary" onclick="closeModal()">탐험 계속하기</button></div>`)}
