function villageHouse(x,z,type){let p=project(x,0,z),s=scale;ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);ctx.fillStyle='#35573c20';ctx.beginPath();ctx.ellipse(0,.1,1.4,.35,0,0,7);ctx.fill();if(type===0){ctx.fillStyle=phase?'#7f719d':'#ad8a63';ctx.beginPath();ctx.roundRect(-.9,-2.7,1.8,2.9,.4);ctx.fill();ctx.strokeStyle='#886d51';ctx.lineWidth=.06;for(let n=0;n<5;n++){ctx.beginPath();ctx.moveTo(-.7+n*.33,-2.4);ctx.quadraticCurveTo(-.9+n*.4,-1,-.7+n*.33,.1);ctx.stroke()}ctx.fillStyle='#5b7650';for(let n=0;n<5;n++){ctx.beginPath();ctx.ellipse(Math.sin(n*2)*.9,-3.05+Math.cos(n*2)*.4,1.15,.75,0,0,7);ctx.fill()}ctx.fillStyle='#8bac6a';ctx.beginPath();ctx.ellipse(-.25,-3.6,1.3,.7,-.2,0,7);ctx.fill()}else{ctx.fillStyle='#f5dec0';ctx.beginPath();ctx.roundRect(-1.1,-1.9,2.2,2,.18);ctx.fill();ctx.fillStyle=phase?'#a88ac5':'#cf927e';ctx.beginPath();ctx.moveTo(-1.5,-1.8);ctx.quadraticCurveTo(-1.2,-3.1,0,-3.4);ctx.quadraticCurveTo(1.25,-3.1,1.5,-1.8);ctx.closePath();ctx.fill();ctx.fillStyle='#f5e6cc';for(let j=0;j<5;j++){ctx.beginPath();ctx.ellipse(Math.sin(j*7)*.9,-2.2-(j%2)*.45,.17,.12,0,0,7);ctx.fill()}}ctx.fillStyle='#6f6253';ctx.beginPath();ctx.roundRect(-.35,-1.05,.7,1.2,[.35,.35,0,0]);ctx.fill();ctx.fillStyle='#ffe3a0';ctx.beginPath();ctx.arc(.55,-1.5,.23,0,7);ctx.fill();ctx.strokeStyle='#827159';ctx.lineWidth=.05;ctx.stroke();ctx.fillStyle='#e7d3ab';ctx.fillRect(-.55,.05,1.1,.14);ctx.restore();ctx.font='bold 12px sans-serif';ctx.textAlign='center';ctx.fillStyle=phase?'#fff':'#47664c';ctx.fillText(type===0?'바람나무 쉼터':'도토리 공방',p.x,p.y+scale*.5)}
function villageDecor(){for(let n=0;n<32;n++){let x=Math.sin(n*18.3)*10,z=Math.cos(n*8.8)*10,p=project(x,0,z);ctx.fillStyle=phase?'#dbc7f1':'#fff4c6';for(let k=0;k<5;k++){ctx.beginPath();ctx.arc(p.x+Math.sin(k*1.26)*4,p.y+Math.cos(k*1.26)*3,2.8,0,7);ctx.fill()}ctx.fillStyle='#e7b961';ctx.beginPath();ctx.arc(p.x,p.y,2,0,7);ctx.fill()}for(let n=0;n<8;n++){let p=project(-8+n*2.3,0,-9);ctx.fillStyle='#ba9a70';ctx.fillRect(p.x-3,p.y-18,6,22);ctx.fillStyle='#f6d8a1';ctx.beginPath();ctx.arc(p.x,p.y-23,7,0,7);ctx.fill()}}
