 for(let n=0;n<0;n++){let x=forestRand(n*2)*24-12,z=forestRand(n*2+1)*24-12;if(Math.abs(x)<.6||Math.abs(z)<.6)continue;let p=project(x,.02,z),s=scale/45,h=4+forestRand(n+900)*9;ctx.strokeStyle=(phase?['#758a9a','#9caec1','#668e9b']:['#649650','#7aab56','#9bc366','#4f8848'])[n%4];ctx.lineWidth=1.2*s;ctx.beginPath();ctx.moveTo(p.x-4*s,p.y);ctx.quadraticCurveTo(p.x-7*s,p.y-h*s,p.x-8*s,p.y-h*s);ctx.moveTo(p.x,p.y);ctx.quadraticCurveTo(p.x-2*s,p.y-h*1.3*s,p.x+2*s,p.y-h*1.4*s);ctx.moveTo(p.x+3*s,p.y);ctx.quadraticCurveTo(p.x+8*s,p.y-h*s,p.x+8*s,p.y-h*.8*s);ctx.stroke();}
 for(let n=0;n<95;n++){let x=forestRand(n+3200)*23-11.5,z=forestRand(n+3700)*23-11.5,p=project(x,0,z),s=scale/45;ctx.fillStyle=['#b2b39a','#a0a88e','#c1bea4'][n%3];ctx.beginPath();ctx.ellipse(p.x,p.y,5*s,3*s,-.25,0,7);ctx.fill();ctx.strokeStyle='#dde0bd';ctx.lineWidth=s;ctx.beginPath();ctx.moveTo(p.x-3*s,p.y-s);ctx.lineTo(p.x,p.y-2*s);ctx.stroke();}
