drawLab=function(){let ready=fusionPick.length===2;modal(`<button class="close" onclick="${indoors?'showRoom()':'closeModal()'}">×</button><span class="tag">LUMI'S EVOLUTION WORKSHOP</span><h2>루미의 진화 작업대</h2><div class="odds"><span>✨ 예쁜 진화형 <b>1/8 · 12.5%</b></span><span>🥔 익살 변이형 <b>7/8 · 87.5%</b></span></div><p>수집한 서로 다른 친구 두 마리를 골라 봐. <b>같은 조합으로 계속 재도전</b>할 수 있어!<br>매번 독립 추첨이라 8번 안에 성공이 보장되지는 않아. 원래 친구는 유지되고 비용은 없어.</p>${caught.size<2?'<p class="notice">숲에서 친구를 2마리 이상 모으면 합성할 수 있어요.</p>':''}<div class="fusion-slots">${[0,1].map(n=>`<div>${fusionPick[n]===undefined?'<span>＋</span>':svg(fusionPick[n])}</div>`).join('<b>+</b>')}</div><div class="grid">${[...caught].sort((a,b)=>a-b).map(i=>`<button class="dexitem ${fusionPick.includes(i)?'chosen':''}" onclick="selectFusion(${i})">${svg(i)}<b>${creatures[i][0]}</b></button>`).join('')}</div><p><button class="primary" ${!ready?'disabled':''} onclick="doFusion()">✨ 진화 실험 시작</button> <button class="secondary" onclick="${indoors?'talkNpc()':'enterWorkshop()'}">루미와 이야기</button></p><h3>진화 기록 · ${evolutionLog.length}회 / 예쁜 진화 ${evolutionLog.filter(r=>r.tier==='rare').length}회</h3><div class="grid">${evolutionLog.slice(-20).reverse().map(r=>`<div class="dexitem ${r.tier==='rare'?'rare-result':''}">${evolutionSvg(r)}<b>${evolutionName(r)}</b><p style="font-size:10px">${r.tier==='rare'?'✨ 예쁜 진화':'🥔 익살 변이'}</p></div>`).join('')}</div><small>최근 20개 결과 표시 · 친구 합성은 게임 속 상상 설정이에요.</small>`)};
doFusion=function(){if(fusionBusy||fusionPick.length!==2)return;let [a,b]=[...fusionPick].sort((a,b)=>a-b);if(a===b||!caught.has(a)||!caught.has(b))return;fusionBusy=true;let r={a,b,tier:rollEvolution(),variant:(a+b+evolutionLog.length)%4};evolutionLog.push(r);gameStorage.setItem('sparkwood-evolutions-v1',JSON.stringify(evolutionLog));modal(`<div class="intro"><span class="tag">${r.tier==='rare'?'RARE EVOLUTION · 1/8':'UNEXPECTED FRIEND · 7/8'}</span><div class="fusion-born">${evolutionSvg(r)}</div><h2>${evolutionName(r)} 등장!</h2><p>${r.tier==='rare'?'“우와, 반짝이는 진화에 성공했어!”':'“어라? 조금 엉뚱한 친구가 나왔네!”'}<br>루미: ${r.tier==='rare'?'정말 멋진 친구야. 도감에 기록해 둘게!':'이 친구도 네 모험을 응원해. 다시 도전해 볼래?'}</p><button class="primary" onclick="doFusion()">같은 조합으로 다시 도전</button> <button class="secondary" onclick="drawLab()">다른 친구 고르기</button> <button class="secondary" onclick="${indoors?'showRoom()':'closeModal()'}">잠깐 쉬기</button></div>`);fusionBusy=false;};
