function baseRef(i){return {key:'b'+i,label:creatures[i][0],a:i,b:i,art:svg(i)}}
function fusionRef(r){return {key:'e'+r.id,label:evolutionName(r),a:r.a,b:r.b,art:evolutionSvg(r)}}
function availableFriends(){return [...caught].map(baseRef).concat(evoFriends.map(fusionRef))}
function resolveFriend(key){return availableFriends().find(r=>r.key===key)}
function consumeFriend(key){if(key[0]==='b')caught.delete(Number(key.slice(1)));else evoFriends=evoFriends.filter(r=>r.id!==key.slice(1))}
const basicEvolutionName=evolutionName,basicEvolutionSvg=evolutionSvg;
evolutionName=function(r){return r.tier==='legend'?'천상의 '+['별꽃 여왕','달빛 구미호','오로라 공주','수정 수호룡'][r.variant]:basicEvolutionName(r)};
evolutionSvg=function(r){if(r.tier!=='legend')return basicEvolutionSvg(r);return basicEvolutionSvg({...r,tier:'rare'}).replace('<ellipse cx="102"', '<path d="M99 14Q3 5 10 106L52 124M101 14Q197 5 190 106L148 124" fill="#f7e3ff" stroke="#dfbeef" stroke-width="2"/><ellipse cx="100" cy="28" rx="37" ry="10" fill="none" stroke="#f4c958" stroke-width="5"/><ellipse cx="102"')};
let selectedEvoId=null;
