fusionLab=function(){fusionPick=[];drawLab()};
function evoCard(r){return `<button class="dexitem ${r.tier!=='goofy'?'rare-result':''}" onclick="inspectEvolution('${r.id}')">${evolutionSvg(r)}<b>${evolutionName(r)}</b><p style="font-size:11px">${r.locked?'최종 진화 완료':r.attempts+'/5회 · 수집됨'}</p></button>`}
showDex=function(){modal(`<button class="close" onclick="closeModal()">×</button><span class="tag">MY COLLECTION</span><h2>내 친구 도감</h2><p>기본 친구 ${caught.size}마리 · 합성 친구 ${evoFriends.length}마리<br>합성 재료로 사용한 친구는 여기서 사라져요. 기본 친구는 숲에서 다시 만날 수 있어요.</p><h3>과학 친구 · ${creatures.length}종</h3><div class="grid">${creatures.map((c,i)=>`<button class="dexitem" onclick="review(${i})"><div style="filter:${caught.has(i)?'none':'grayscale(1) opacity(.3)'}">${svg(i)}</div><b>${c[0]}</b><p style="font-size:10px">${caught.has(i)?'보유 중':'미보유'} · ${c[1]}</p></button>`).join('')}</div><h3>수집한 합성 친구</h3><div class="grid">${evoFriends.map(evoCard).join('')||'<p>두 친구를 합성해 첫 친구를 만들어 봐!</p>'}</div><p><button class="primary" onclick="fusionLab()">합성 공방</button> <button class="secondary" onclick="resetGame()">새로 시작</button></p>`)};
drawLab=function(){fusionPick=fusionPick.filter(k=>resolveFriend(k));modal(`<button class="close" onclick="${indoors?'showRoom()':'closeModal()'}">×</button><span class="tag">EVOLUTION WORKSHOP</span><h2>두 친구가 새로운 친구로!</h2><p><b>재료 두 마리는 소모</b>되고, 결과 친구가 도감에 자동 수집돼요. 합성 친구도 재료로 사용할 수 있어요.</p><div class="odds"><span>1~5회: 예쁜 진화 <b>1/8 · 12.5%</b>변이형 7/8</span><span>6회: 마지막 도전 <b>초희귀 진화 1/8 · 소멸 7/8</b>결과와 관계없이 재도전 종료</span></div><div class="fusion-slots">${[0,1].map(i=>`<div>${resolveFriend(fusionPick[i])?.art||'<span>＋</span>'}</div>`).join('<b>+</b>')}</div><div class="grid">${availableFriends().map(r=>`<button class="dexitem ${fusionPick.includes(r.key)?'chosen':''}" onclick="selectFusion('${r.key}')">${r.art}<b>${r.label}</b></button>`).join('')}</div><p><button class="primary" ${fusionPick.length!==2?'disabled':''} onclick="doFusion()">두 친구를 소모하고 합성</button> <button class="secondary" onclick="showDex()">도감 보기</button></p><small>첫 합성이 1회입니다. 결과 친구마다 횟수가 저장됩니다. 기존 친구 재도전은 도감에서 선택하세요.</small>`)};
function variantRoll(){let x=new Uint32Array(1);crypto.getRandomValues(x);return x[0]%4}
doFusion=function(){if(fusionBusy||fusionPick.length!==2)return;let a=resolveFriend(fusionPick[0]),b=resolveFriend(fusionPick[1]);if(!a||!b||a.key===b.key)return;fusionBusy=true;let r={id:'friend-'+nextFriendId++,a:a.a,b:b.b,tier:rollEvolution(),variant:variantRoll(),attempts:1,alive:true,locked:false};consumeFriend(a.key);consumeFriend(b.key);evoFriends.push(r);fusionPick=[];persist();fusionBusy=false;inspectEvolution(r.id)};
function inspectEvolution(id){let r=evoFriends.find(r=>r.id===id);if(!r)return;selectedEvoId=id;modal(`<div class="intro"><span class="tag">${r.tier==='legend'?'ULTIMATE EVOLUTION':'COLLECTED FRIEND'}</span><div class="fusion-born">${evolutionSvg(r)}</div><h2>${evolutionName(r)}</h2><p>도감에 수집 완료! · ${r.attempts}회 도전<br>${r.locked?'최종 진화가 완료되어 더는 주사위를 굴릴 수 없어.':r.attempts<5?'같은 친구의 모습으로 다시 도전할 수 있어.':'5회 도전을 마쳤어. 지금 모습을 간직하거나 마지막 위험한 도전을 선택해.'}</p>${r.locked?'':`<button class="primary" onclick="${r.attempts===5?'confirmFinal':'retryEvolution'}('${id}')">${r.attempts===5?'6번째 최종 도전 안내':'주사위 다시 굴리기 ('+(r.attempts+1)+'/5)'}</button>`} <button class="secondary" onclick="showDex()">이 모습으로 보관</button></div>`)}
function confirmFinal(id){let r=evoFriends.find(r=>r.id===id);if(!r||r.attempts!==5||r.locked)return;modal(`<div class="intro"><h2>마지막 주사위를 굴릴까?</h2><div class="fusion-born">${evolutionSvg(r)}</div><p><b>1/8: 초희귀 진화 · 7/8: 이 친구 소멸</b><br>실패하면 이 합성 친구가 도감에서 사라져요.<br>성공해도 이번이 마지막 주사위예요.</p><button class="primary" onclick="retryEvolution('${id}',true)">위험을 감수하고 6번째 도전</button> <button class="secondary" onclick="inspectEvolution('${id}')">현재 모습 보관</button></div>`)}
function retryEvolution(id,finalConfirmed=false){let r=evoFriends.find(r=>r.id===id);if(!r||r.locked||r.attempts>=6||fusionBusy)return;if(r.attempts===5&&!finalConfirmed){confirmFinal(id);return}fusionBusy=true;r.attempts++;let tier=rollEvolution();r.variant=variantRoll();if(r.attempts===6){r.locked=true;if(tier==='rare')r.tier='legend';else{r.alive=false;lostFriends.push({...r});evoFriends=evoFriends.filter(x=>x.id!==id)}}else r.tier=tier;persist();fusionBusy=false;if(!r.alive){modal(`<div class="intro"><span class="tag">FINAL ROLL · POOF!</span><div style="font-size:90px">💥</div><h2>펑! 친구가 별가루로 흩어졌어.</h2><p>6번째 도전에 실패해서 이 합성 친구가 도감에서 사라졌어.<br>다른 친구를 모아 새로운 합성에 도전해 봐.</p><button class="primary" onclick="showDex()">도감 확인</button> <button class="secondary" onclick="closeModal()">숲으로 돌아가기</button></div>`)}else inspectEvolution(id)};
// Third wrong answer triggers a turn-based battle after both hints.
let battle=null;
const preBattleAnswer=answer;
answer=function(i){if(solved||battle?.running)return;if(i!==creatures[active][7]&&wrong>=2){wrong++;startBattle();return}preBattleAnswer(i)};
function startBattle(){battle={running:true,hp:100,enemy:90,energy:2,turn:0,message:'힌트 두 번으로도 안 됐어? 그럼 실력으로 겨뤄 보자!'};drawBattle()}
function battleIntent(){return battle.turn%3===2?'강력한 방전 (30 피해)':'찌릿 공격 (14 피해)'}
function drawBattle(){modal(`<span class="tag">SCIENCE DUEL · 전투로 수집하기</span><h2>${creatures[active][0]}의 도전!</h2><div class="duel"><div>${avatarSvg(avatar)}<b>나 · HP ${battle.hp}/100</b><progress value="${battle.hp}" max="100"></progress></div><strong>VS</strong><div>${svg(active)}<b>${creatures[active][0]} · HP ${battle.enemy}/90</b><progress value="${battle.enemy}" max="90"></progress></div></div><p class="notice">${battle.message}</p><p><b>다음 적 행동: ${battleIntent()}</b> · 내 에너지 ${battle.energy}/3</p><div class="battle-actions"><button class="primary" onclick="battleTurn('attack')">공격 · 22 피해</button><button class="primary" ${battle.energy<2?'disabled':''} onclick="battleTurn('skill')">전기 스킬 · 38 피해 / 에너지 2</button><button class="secondary" onclick="battleTurn('guard')">방어 · 피해 75% 감소 / 에너지 +1</button><button class="secondary" onclick="battleTurn('charge')">충전 · HP +20 / 에너지 +1</button><button class="secondary" onclick="fleeBattle()">물러나기</button></div><small>적의 강한 공격은 방어로 버티세요. 승리하면 정답 해설을 확인하고 수집할 수 있어요.</small>`)}
function battleTurn(action){if(!battle?.running)return;if(action==='skill'&&battle.energy<2)return;let msg='',guard=false;if(action==='attack'){battle.enemy-=22;msg='공격으로 22 피해!'}else if(action==='skill'){battle.enemy-=38;battle.energy-=2;msg='전기 스킬! 38 피해!'}else if(action==='guard'){guard=true;battle.energy=Math.min(3,battle.energy+1);msg='방어하며 에너지를 모았어.'}else if(action==='charge'){battle.hp=Math.min(100,battle.hp+20);battle.energy=Math.min(3,battle.energy+1);msg='체력과 에너지를 충전했어.'}else return;if(battle.enemy<=0){battle.enemy=0;battle.running=false;solved=true;refusal=1;modal(`<div class="intro">${svg(active)}<span class="tag">BATTLE WON</span><h2>“쳇, 제법인데? 같이 가 주지!”</h2><p>${creatures[active][9]}</p><button class="primary" onclick="capture()">승리한 친구 수집하기</button></div>`);return}let damage=battle.turn%3===2?30:14;if(guard)damage=Math.ceil(damage*.25);battle.hp=Math.max(0,battle.hp-damage);battle.turn++;battle.message=msg+' 상대 공격으로 '+damage+' 피해를 받았어.';if(battle.hp===0){battle.running=false;modal(`<div class="intro"><h2>“후후, 이번 판은 내 승리네!”</h2><p>다시 문제를 풀거나 전투에 재도전할 수 있어.<br>${creatures[active][9]}</p><button class="primary" onclick="startBattle()">전투 재도전</button> <button class="secondary" onclick="wrong=0;solved=false;question()">문제 다시 풀기</button> <button class="secondary" onclick="closeModal()">돌아가기</button></div>`)}else drawBattle()}
function fleeBattle(){if(battle)battle.running=false;closeModal()}
const oldEncounter4=encounter;encounter=function(){if(battle)battle.running=false;oldEncounter4()};
// 10-minute day/night cycle, anchored to page-open time; background-tab time counts.
const skyStartedAt=Date.now();
function skyPhase(elapsed){let t=((elapsed%600000)+600000)%600000;return {night:t>=300000,remaining:300000-(t%300000)}}
const beforeSkyRender=render;
render=function(ts){beforeSkyRender(ts);let state=skyPhase(Date.now()-skyStartedAt),sec=Math.ceil(state.remaining/1000);{const text=`${state.night?'☾ 밤':'☀ 낮'} · ${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')} 후 ${state.night?'낮':'밤'}`;if($('sky-clock').textContent!==text)$('sky-clock').textContent=text;}if(state.night){ctx.fillStyle='#14244a66';ctx.fillRect(0,0,W,H);for(let n=0;n<45;n++){let x=forestRand(n+7000)*W,y=forestRand(n+7100)*H;ctx.fillStyle=`rgba(255,244,176,${.3+.3*Math.sin(time*1.8+n)})`;ctx.beginPath();ctx.arc(x,y,1.4,0,7);ctx.fill()}}};
help=function(){modal(`<button class="close" onclick="closeModal()">×</button><h2>찌릿숲 탐험 안내</h2><p>방향키 / WASD / 화면 화살표로 이동 · E로 만나기.<br>에보나이트·코일·검전기·건전지를 포함해 총 17문제!<br>오답 1·2회: 단계별 힌트. 세 번째 오답: 전투 시작.<br>문제를 맞히거나 전투에서 승리하면 친구를 수집해요.</p><p>낮 5분 → 밤 5분, 10분마다 반복합니다.<br>공방 문 근처에서 E를 누르면 NPC 루미를 만나요.</p><p>합성 재료 두 마리는 사라지고 결과 친구가 도감에 남아요.<br>첫 합성부터 5회까지: 예쁜 진화 1/8, 변이 7/8.<br>선택 가능한 6번째 최종 도전: 초희귀 진화 1/8, 소멸 7/8.<br>6회 이후에는 재도전할 수 없어요. 모든 확률은 독립 추첨이에요.</p><button class="primary" onclick="closeModal()">모험 계속하기</button>`)};
const oldNpc4=talkNpc;talkNpc=function(){oldNpc4();let speech=$('content').querySelector('.speech p');if(speech)speech.innerHTML='두 친구를 재료로 새 친구를 만들 수 있어! 재료는 사라지고 결과는 도감에 남아.<br>5회까지는 예쁜 진화 1/8, 변이 7/8이야. 6회째에는 초희귀 진화 1/8, 소멸 7/8!<br>자신 있으면 작업대로 와 봐. 무료 의상실도 열려 있어.'};
