function illustratedRock(t){let p=project(t.x,0,t.z),s=scale,h=t.h;ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);softEllipse(0,0,.8,.2,'#071f2c26');let g=ctx.createLinearGradient(-.6,-h, .65,0);g.addColorStop(0,mapIndex===5?'#967774':'#8a9ba9');g.addColorStop(.42,mapIndex===5?'#634d58':'#516b82');g.addColorStop(1,mapIndex===5?'#342d40':'#263c56');ctx.fillStyle=g;ctx.beginPath();ctx.moveTo(-.8,.03);ctx.bezierCurveTo(-1,-h*.45,-.55,-h*.6,-.6,-h);ctx.bezierCurveTo(-.55,-h*1.4,.25,-h*1.3,.42,-h);ctx.bezierCurveTo(.6,-h*.8,.9,-.5,.85,.06);ctx.quadraticCurveTo(0,.28,-.8,.03);ctx.fill();ctx.strokeStyle='#d3d4cf22';ctx.lineWidth=.035;ctx.beginPath();ctx.moveTo(-.44,-h);ctx.bezierCurveTo(-.6,-h*.6,-.1,-.5,-.3,-.12);ctx.stroke();ctx.restore();}
function canopyTree(t){let p=project(t.x,0,t.z),s=scale,h=t.h+1;ctx.save();ctx.translate(p.x,p.y);ctx.scale(s,s);softEllipse(0,.02,1,.28,'#335f3924');let bark=ctx.createLinearGradient(-.3,0,.3,0);bark.addColorStop(0,'#6d6651');bark.addColorStop(.5,'#b89b70');bark.addColorStop(1,'#756b51');ctx.fillStyle=bark;ctx.beginPath();ctx.moveTo(-.45,.1);ctx.bezierCurveTo(-.05,-.4,-.15,-1,-.25,-h);ctx.lineTo(.28,-h);ctx.bezierCurveTo(.13,-1,.3,-.3,.55,.15);ctx.quadraticCurveTo(.1,0,-.45,.1);ctx.fill();ctx.strokeStyle='#d2b88866';ctx.lineWidth=.04;ctx.beginPath();ctx.moveTo(-.03,-h);ctx.quadraticCurveTo(-.12,-.6,.16,-.08);ctx.stroke();for(let n=0;n<10;n++){let a=n*2.4,r=.25+n%3*.32,cx=Math.cos(a)*r,cy=-h+Math.sin(a)*r*.65;let g=ctx.createRadialGradient(cx-.22,cy-.3,.02,cx,cy,.82);g.addColorStop(0,['#c3db92','#a8d184','#b7d991'][n%3]);g.addColorStop(.45,['#82b46e','#87b771','#95c27d'][n%3]);g.addColorStop(1,'#4a8665');ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(cx,cy,.75,.58,-.15,0,7);ctx.fill();}ctx.restore();}
