tree=function(t){if(Math.abs(t.z)<1.8&&Math.abs(t.x)>8)return;if(t.z>8){ctx.save();ctx.globalAlpha=.75;}if(mapIndex===0||mapIndex===1&&t.x<2)canopyTree(t);else if(mapIndex<3)palmTree(t);else if(mapIndex===3)coralTree(t);else illustratedRock(t);if(t.z>8)ctx.restore();};
